def transfer_reference() -> str:
    """New pay-by-bank-transfer reference: 12 chars in three dash-separated groups of four,
    e.g. "K7QM-X2PA-9TBR". Same unambiguous alphabet as the shop's other customer-facing codes,
    so it reads clearly over the phone and from printed invoices."""
